import warnings; warnings.filterwarnings('ignore')
import pandas as pd, numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from sklearn.model_selection import StratifiedGroupKFold, GroupKFold, cross_val_predict
from sklearn.ensemble import ExtraTreesClassifier, RandomForestClassifier, HistGradientBoostingClassifier, ExtraTreesRegressor, RandomForestRegressor, HistGradientBoostingRegressor
from sklearn.metrics import roc_auc_score, average_precision_score, mean_absolute_error, r2_score
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.linear_model import LogisticRegression
tr=pd.read_csv('cdft_topo_sp_eg_train.csv'); po=pd.read_csv('cdft_topo_pool.csv'); all=pd.concat([tr,po],ignore_index=True)
props=['Z','row','group','X','atomic_radius','atomic_mass','electron_affinity','ionization_energy','average_ionic_radius','mendeleev_no']
def val(e,p):
 try: return float(getattr(e,p,None))
 except: return np.nan
def feat(r):
 s=Structure.from_str(r.poscar,fmt='poscar'); comp=s.composition.fractional_composition; els=list(comp.elements); w=np.array([comp[e] for e in els]); w=w/w.sum(); f={}
 f.update(nelem=len(els),entropy=-sum(w*np.log(w)),nsites=len(s),vpa=s.volume/len(s),density=s.density)
 lens=sorted(s.lattice.abc); f.update(lat_mid_min=lens[1]/lens[0],lat_max_min=lens[2]/lens[0])
 for i,a in enumerate(sorted(s.lattice.angles)): f['angle'+str(i)]=a
 sg=SpacegroupAnalyzer(s,symprec=.1).get_space_group_number(); f['sg']=sg
 bins=[2,15,74,142,167,194,230]; cs=next(i for i,x in enumerate(bins) if sg<=x)
 for i in range(7): f['cs'+str(i)]=int(i==cs)
 for block in 'spdf': f['block_'+block]=sum(x for e,x in zip(els,w) if e.block==block)
 f['metal_frac']=sum(x for e,x in zip(els,w) if e.is_metal)
 for z in range(1,104): f['el_'+str(z)]=sum(x for e,x in zip(els,w) if e.Z==z)
 for p in props:
  a=np.array([val(e,p) for e in els]); mask=np.isfinite(a); aa=a[mask]; ww=w[mask]; ww=ww/ww.sum() if len(ww) else ww
  if len(aa):
   mu=sum(aa*ww); vals=[mu,np.sqrt(sum(ww*(aa-mu)**2)),aa.min(),aa.max(),aa.max()-aa.min()]
  else: vals=[0]*5
  for st,v in zip(['mean','std','min','max','range'],vals): f[p+'_'+st]=v
 dm=s.distance_matrix.copy(); dm[dm<1e-6]=np.nan; nn=np.nanmin(dm,axis=1) if len(s)>1 else np.array([0])
 for st,fun in [('mean',np.nanmean),('std',np.nanstd),('min',np.nanmin),('max',np.nanmax)]: f['nn_'+st]=fun(nn)
 return f
X=pd.DataFrame([feat(r) for _,r in all.iterrows()]).replace([np.inf,-np.inf],0).fillna(0); Xt=X.iloc[:len(tr)]; Xp=X.iloc[len(tr):]; y=(tr.band_gap>=1).astype(int).values; groups=tr.formula.values
cv=StratifiedGroupKFold(5,shuffle=True,random_state=12)
clfs={'ET':ExtraTreesClassifier(n_estimators=500,min_samples_leaf=2,max_features=.7,class_weight='balanced',random_state=1),'RF':RandomForestClassifier(n_estimators=500,min_samples_leaf=2,max_features=.7,class_weight='balanced',random_state=1),'HGB':HistGradientBoostingClassifier(max_iter=250,max_leaf_nodes=12,l2_regularization=2,learning_rate=.04,class_weight='balanced',random_state=1),'LR':make_pipeline(StandardScaler(),LogisticRegression(C=.08,class_weight='balanced',max_iter=3000))}
print('GAP CLASS CV')
for n,m in clfs.items():
 p=cross_val_predict(m,Xt,y,groups=groups,cv=cv,method='predict_proba')[:,1]; print(n,'AUC',round(roc_auc_score(y,p),3),'AP',round(average_precision_score(y,p),3),'pos',round(p[y==1].mean(),2),'neg',round(p[y==0].mean(),2)); m.fit(Xt,y); pp=m.predict_proba(Xp)[:,1]; print(pd.DataFrame({'id':po.candidate_id,'f':po.formula,'p':pp}).sort_values('p',ascending=False).head(25).to_string(index=False))
print('\nGAP REG CV')
regs={'ET':ExtraTreesRegressor(n_estimators=500,min_samples_leaf=2,max_features=.8,random_state=2),'RF':RandomForestRegressor(n_estimators=500,min_samples_leaf=2,max_features=.8,random_state=2),'HGB':HistGradientBoostingRegressor(max_iter=250,max_leaf_nodes=12,l2_regularization=2,learning_rate=.04,random_state=2)}
for n,m in regs.items():
 p=cross_val_predict(m,Xt,tr.band_gap,groups=groups,cv=GroupKFold(5)); print(n,'MAE',round(mean_absolute_error(tr.band_gap,p),3),'R2',round(r2_score(tr.band_gap,p),3)); m.fit(Xt,tr.band_gap); pp=m.predict(Xp); print(pd.DataFrame({'id':po.candidate_id,'f':po.formula,'eg':pp}).sort_values('eg',ascending=False).head(25).to_string(index=False))
print('\nSPILL REG')
for n,m in regs.items():
 p=cross_val_predict(m,Xt,tr.spillage,groups=groups,cv=GroupKFold(5)); print(n,'MAE',round(mean_absolute_error(tr.spillage,p),3),'R2',round(r2_score(tr.spillage,p),3),'rho',round(pd.Series(tr.spillage).corr(pd.Series(p),method='spearman'),3)); m.fit(Xt,tr.spillage); pp=m.predict(Xp); print(pd.DataFrame({'id':po.candidate_id,'f':po.formula,'spill':pp}).sort_values('spill',ascending=False).head(25).to_string(index=False))
